// Fixture identity constants (no-coincidence discipline: independent of the
// plugin suites' and the other joints' fixtures). The alphabetical story is
// load-bearing: Alpha sorts before Zulu by display name AND by path, so the
// pre-learning tie serves Alpha first (the alphabetical floor) and only the
// learned weights can flip the order.
const (
	qaRecsDirAlpha   = "Alpha Show S01"
	qaRecsEpAlpha    = "Alpha Show S01E01.mkv"
	qaRecsDirZulu    = "Zulu Show S01"
	qaRecsEpZulu     = "Zulu Show S01E01.mkv"
	qaRecsTitleAlpha = "Alpha Show" // the shared grammar's season cut of dir Alpha
	qaRecsTitleZulu  = "Zulu Show"  // the shared grammar's season cut of dir Zulu
	qaRecsIDAlpha    = 9101         // Alpha's anime on the stub upstream
	qaRecsIDZulu     = 9102         // Zulu's anime on the stub upstream

	// Both fixtures are qaSerialMedia lavfi files (~0.3 s), so a stored
	// position of 2 s sits at/above 90% of any probed duration — the
	// completion rule's satisfied side.
	qaRecsWatchPos = 2

	// qaRecsFloor is the completion fraction — the mirror of cmd/mellifera's
	// watchedDurationFloor (0.9); duplicated because package main cannot be
	// imported (the pbStreamsLane drift-warning precedent).
	qaRecsFloor = 0.9

	// qaRecsRecsInterval is the recs task's ticker period — the mirror of
	// recsInterval (60 s). It never fires in the test's lifetime; the wake
	// channel drives every pass.
	qaRecsRecsInterval = 60 * time.Second

	// qaRecsApplyTimeout bounds the wake-poked learning pass (the pass runs
	// within moments of the completion insert; the bound absorbs the
	// goroutine handoff and the store walk).
	qaRecsApplyTimeout = 15 * time.Second

	qaRecsUpstreamSearch = "/api/animes"
	qaRecsUpstreamByID   = "/api/animes/"
	qaRecsHost           = "shikimori.io"

	// The expected score values (the score model's integers land on the wire
	// exactly): base weights sum one point per tag; the learned pass adds one
	// point per watched series' tag.
	qaRecsScoreBase    = 2.0 // two tags, zero interest — both series, pre-learning
	qaRecsScoreLearned = 4.0 // two tags, one applied completion — Zulu post-learning
)

// The two genres per series, as the plugin's RU-first namespace carries them.
// Exactly two per series is the equal-count guard: the tag count contributes
// identically to both series, so only the LEARNED weight can separate them.
var (
	qaRecsGenresAlpha = []string{"Драма", "Комедия"}
	qaRecsGenresZulu  = []string{"Экшен", "Фантастика"}
)

// qaRecsAnime builds one upstream anime payload (the shape the plugin's
// Convert decodes; the description is load-bearing — the synopsis carrier
// test is what makes the namespace the genres winner for BOTH the janitor's
// resolver and the api's projection). score is a decimal STRING upstream.
func qaRecsAnime(id int, name, russian string, genres []string) map[string]any {
	arr := make([]any, len(genres))
	for i, g := range genres {
		arr[i] = map[string]any{"name": g, "russian": g}
	}
	return map[string]any{
		"id": id, "name": name, "russian": russian, "kind": "tv", "status": "released",
		"score": "8.0", "episodes": 1, "aired_on": "2020-01-01",
		"description": "qa recs stub " + name,
		"url":         qaRecsUpstreamSearch + "/" + strconv.Itoa(id) + "-qa",
		"image":       map[string]any{"original": "/images/animes/" + strconv.Itoa(id) + ".jpg"},
		"genre":       arr,
	}
}

// The stub's per-title search lists (one candidate each — candidate preference
// scoring is the shikimori joint's concern, not this one) and by-id objects.
var (
	qaRecsSearchList = map[string][]map[string]any{
		qaRecsTitleAlpha: {qaRecsAnime(qaRecsIDAlpha, qaRecsTitleAlpha, qaRecsTitleAlpha, qaRecsGenresAlpha)},
		qaRecsTitleZulu:  {qaRecsAnime(qaRecsIDZulu, qaRecsTitleZulu, qaRecsTitleZulu, qaRecsGenresZulu)},
	}
	qaRecsByID = map[string]map[string]any{
		strconv.Itoa(qaRecsIDAlpha): qaRecsAnime(qaRecsIDAlpha, qaRecsTitleAlpha, qaRecsTitleAlpha, qaRecsGenresAlpha),
		strconv.Itoa(qaRecsIDZulu):  qaRecsAnime(qaRecsIDZulu, qaRecsTitleZulu, qaRecsTitleZulu, qaRecsGenresZulu),
	}
)

// qaRecsStub is the fake upstream: it just serves the payloads above (the
// fetch contract — pacing, UA, anchoring — is the shikimori joint's
// already-proven ground, not this joint's).
type qaRecsStub struct {
	srv *httptest.Server
}

func qaRecsStartStub(t *testing.T) *qaRecsStub {
	t.Helper()
	mux := http.NewServeMux()
	mux.HandleFunc(qaRecsUpstreamSearch, func(w http.ResponseWriter, r *http.Request) {
		list, ok := qaRecsSearchList[r.URL.Query().Get("search")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaShikWriteJSON(t, w, list) // the shared stub JSON writer (header + encode)
	})
	mux.HandleFunc(qaRecsUpstreamByID, func(w http.ResponseWriter, r *http.Request) {
		e, ok := qaRecsByID[strings.TrimPrefix(r.URL.Path, qaRecsUpstreamByID)]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaShikWriteJSON(t, w, e)
	})
	mux.HandleFunc("/api/graphql", func(w http.ResponseWriter, r *http.Request) {
		// The poster leg (anchored plans): serve a poster URL for whichever
		// id the query names — the body's shape is all the plugin reads.
		body, _ := io.ReadAll(r.Body)
		id := ""
		for _, want := range []string{strconv.Itoa(qaRecsIDAlpha), strconv.Itoa(qaRecsIDZulu)} {
			if strings.Contains(string(body), want) {
				id = want
				break
			}
		}
		if id == "" {
			http.NotFound(w, r)
			return
		}
		qaShikWriteJSON(t, w, map[string]any{
			"data": map[string]any{"animes": []any{map[string]any{
				"poster": map[string]any{"originalUrl": "/uploads/poster/animes/" + id + "/qa-main.webp"},
			}}},
		})
	})
	return &qaRecsStub{srv: httptest.NewServer(mux)}
}

// qaRecsRewrite points the core's fetch at the stub (the qaShikRewrite
// posture: upstream-host requests keep path/query/headers, hit the stub;
// everything else passes through).
type qaRecsRewrite struct {
	stub *url.URL
	next http.RoundTripper
}

func (r *qaRecsRewrite) RoundTrip(req *http.Request) (*http.Response, error) {
	if req.URL.Hostname() == qaRecsHost {
		clone := req.Clone(req.Context())
		clone.URL.Scheme, clone.URL.Host = r.stub.Scheme, r.stub.Host
		req = clone
	}
	return r.next.RoundTrip(req)
}

// qaRecsJoint is one composed recs round-trip world.
type qaRecsJoint struct {
	w       *pbWorld
	stub    *qaRecsStub
	q       *enrich.Queue
	srv     *httptest.Server // the joint's OWN api surface — OnProgress wired
	baseURL string
	lib     int64
	wake    chan struct{} // the recs wake mirror (capacity 1, notifyRecs shape)
}

// qaRecsStartJoint composes the joint: the pbWorld graph + the three metadata
// plugin subprocesses + the real enrich queue (real FetchGate, the
// cmd/mellifera wiring shape) + the scan Notify hook (main.go's shape,
// context.WithoutCancel included) + the mirrored watch detector and recs
// janitor over the REAL store and registry + the joint's own api/web server
// with Deps.OnProgress wired (pbNewWorld's server predates the watch seam and
// stays untouched; this joint drives its own — the main.go composition shape
// for the surfaces the loop needs).
func qaRecsStartJoint(t *testing.T) *qaRecsJoint {
	t.Helper()
	w := pbNewWorld(t) // guards ffmpeg/ffprobe; real store + registry + scanner subprocesses
	tmp := t.TempDir()
	metaCaps := []sdk.Capability{{Type: "metadata_source", ID: "default", ProtoService: "mellifera.metadata.v1.MetadataSource"}}
	paths := map[string]string{
		"serial-parser": buildBinary(t, tmp, "qa-recs-serial-parser", "./plugins/serial-parser"),
		"frame-grabber": buildBinary(t, tmp, "qa-recs-frame-grabber", "./plugins/frame-grabber"),
		"shikimori":     buildBinary(t, tmp, "qa-recs-shikimori", "./plugins/shikimori"),
	}
	for id, path := range paths {
		if err := w.mgr.Load(id, path, metaCaps); err != nil {
			t.Fatalf("load %s: %v", id, err)
		}
		if err := w.mgr.Start(context.Background(), id); err != nil {
			t.Fatalf("start %s: %v", id, err)
		}
	}
	t.Cleanup(func() {
		stopCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		for id := range paths {
			_ = w.mgr.Stop(stopCtx, id)
		}
	})

	j := &qaRecsJoint{w: w, stub: qaRecsStartStub(t)}
	t.Cleanup(j.stub.srv.Close)

	// The stub host swap (no test in this package runs parallel; the cleanup
	// restores before any later test in the binary runs).
	saved := http.DefaultTransport
	stubURL, err := url.Parse(j.stub.srv.URL)
	if err != nil {
		t.Fatalf("parse stub url: %v", err)
	}
	http.DefaultTransport = &qaRecsRewrite{stub: stubURL, next: saved}
	t.Cleanup(func() { http.DefaultTransport = saved })

	// The real enrich queue — the cmd/mellifera wiring shape, FetchGate
	// included (never nil in production).
	deps := enrich.Deps{Store: w.st, Modules: w.reg, Plugins: w.mgr, FetchGate: enrich.NewFetchGate()}
	j.q = enrich.NewQueue(deps, enrich.QueueConfig{Workers: 2, Backoff: 10 * time.Millisecond})
	if err := j.q.Start(context.Background()); err != nil {
		t.Fatalf("queue start: %v", err)
	}
	t.Cleanup(j.q.Stop)
	w.scanDep.Notify = func(ctx context.Context, libraryID int64) {
		j.q.Notify(context.WithoutCancel(ctx), libraryID)
	}

	// The mirrored recs janitor: boot-run, then the janitor select loop over
	// ctx / interval ticker (never fires here) / completion wake — the loop
	// rides a goroutine exactly like main.go's `go jan.run(ctx)`. The cancel
	// context stops it FIRST in cleanup order (LIFO, ahead of pbNewWorld's
	// store close).
	j.wake = make(chan struct{}, 1)
	jctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)
	go qaRecsRunJanitor(jctx, w.st, w.reg, j.wake)

	// The joint's api surface — the main.go composition shape for the loop's
	// surfaces: Scan over the shared Deps, OnProgress carrying the mirrored
	// watch-detect leg.
	apiH := api.New(api.Deps{
		AdminToken: w.token,
		Store:      w.st,
		Scan: func(ctx context.Context, libraryID int64) (scan.Result, error) {
			return scan.Run(ctx, w.scanDep, libraryID)
		},
		OnProgress: qaRecsWatchDetect(w.st, j.wake),
		// ModulePresentation — the composition-root seam (main.go): the api's
		// namer chain, and with it the scored serve's genre resolution, rides
		// this closure (INV2: api imports neither the registry nor enrich).
		// The joint mirrors its load-bearing leg for the scored surfaces —
		// the gate-resolved chain walk over ONE batched prefs read, verbatim
		// AddChainSource order; the title-walk inputs stay unset (the namer
		// skips the walk when absent, and this joint asserts no composed
		// names).
		ModulePresentation: func(ctx context.Context, moduleID string, libraryID int64) (api.ModulePresentation, error) {
			mod, err := w.reg.Get(moduleID)
			if err != nil {
				return api.ModulePresentation{}, err
			}
			prefs, err := w.st.ListMetadataSourcePrefs(ctx, moduleID, []int64{libraryID})
			if err != nil {
				return api.ModulePresentation{}, err
			}
			pres := api.ModulePresentation{}
			for _, src := range enrich.ResolveGates(mod, prefs, libraryID) {
				pres.AddChainSource(src.PluginID, src.Enabled)
			}
			return pres, nil
		},
	})
	j.srv = httptest.NewServer(web.Handler(apiH, web.Options{}))
	t.Cleanup(j.srv.Close)
	j.baseURL = j.srv.URL

	// The fixture tree + the serial library (scan POSTed through the joint's
	// own api so the scan Notify hook feeds the real queue).
	root := t.TempDir()
	qaSerialMedia(t, filepath.Join(root, qaRecsDirAlpha, qaRecsEpAlpha))
	qaSerialMedia(t, filepath.Join(root, qaRecsDirZulu, qaRecsEpZulu))
	j.lib = qaSerialCreateLibrary(t, w.client, j.baseURL, w.token, root, "QA Recs Roundtrip")
	return j
}

// qaRecsRunJanitor runs the mirrored recs task loop — the boot-run, then the
// janitor.run select shape over ctx / ticker / wake (nil wake is never
// selected; here the wake drives every pass). Blocks until ctx is done.
func qaRecsRunJanitor(ctx context.Context, st *store.Store, reg *module.Registry, wake <-chan struct{}) {
	qaRecsSweep(ctx, st, reg) // the boot-run
	ticker := time.NewTicker(qaRecsRecsInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		case <-wake:
		}
		qaRecsSweep(ctx, st, reg)
	}
}

// qaRecsWatchDetect is the completion-detection leg of Deps.OnProgress — the
// mirror of cmd/mellifera's newWatchDetect (package main; every boundary it
// joins — GetItem, InsertWatched, the document shape — is real). Synchronous,
// idempotent, log-and-skip: below the floor or without a stored duration it
// never inserts; a repeat insert is a PK no-op in the store. A write carrying
// the explicit completion intent (watched-states D3: completed true) inserts
// regardless of the floor — intent needs no duration — mirroring the
// production leg.
func qaRecsWatchDetect(st *store.Store, wake chan<- struct{}) func(context.Context, string, int64, bool) {
	return func(ctx context.Context, itemID string, position int64, completed bool) {
		it, err := st.GetItem(ctx, itemID, access.System())
		if err != nil {
			return
		}
		var doc map[string]any
		if err := json.Unmarshal(it.Document, &doc); err != nil {
			return
		}
		if !completed {
			dur, ok := qaRecsProbeDuration(doc["ffprobe"])
			if !ok {
				return // no stored duration — never auto-completes
			}
			if float64(position) < qaRecsFloor*dur {
				return
			}
		}
		if err := st.InsertWatched(ctx, itemID, it.LibraryID, qaRecsSeriesPath(doc), time.Now().UTC(), access.System()); err != nil {
			return
		}
		select { // the notifyRecs shape: capacity-1, default-guarded
		case wake <- struct{}{}:
		default:
		}
	}
}

// qaRecsProbeDuration mirrors thumbProbeDuration: the probe-reported seconds
// from the document's ffprobe namespace — verbatim ffprobe emits
// {"format":{"duration":"<seconds>"}} as a JSON string; a store round-trip
// decodes it to maps, so both shapes are read.
func qaRecsProbeDuration(raw any) (float64, bool) {
	m, ok := raw.(map[string]any)
	if !ok {
		return 0, false
	}
	format, ok := m["format"].(map[string]any)
	if !ok {
		return 0, false
	}
	switch d := format["duration"].(type) {
	case string:
		n, err := strconv.ParseFloat(d, 64)
		if err != nil || n <= 0 {
			return 0, false
		}
		return n, true
	case float64:
		if d <= 0 {
			return 0, false
		}
		return d, true
	default:
		return 0, false
	}
}

// qaRecsSeriesPath mirrors watchSeriesPath: parsed.series_relative_path, the
// episode→series join anchor the watched row persists.
func qaRecsSeriesPath(doc map[string]any) string {
	parsed, _ := doc["parsed"].(map[string]any)
	if parsed == nil {
		return ""
	}
	s, _ := parsed["series_relative_path"].(string)
	return s
}

// qaRecsSweep is the mirror of cmd/mellifera's newRecsSweep body: the derived
// queue read → per-row tag resolution (a resolution failure ends the pass
// BEFORE the row — stamping past it would consume a watch unlearned) → ONE
// ApplyTagWeights transaction (weights + the applied_at stamp commit
// together). applied == 0 writes nothing.
func qaRecsSweep(ctx context.Context, st *store.Store, reg *module.Registry) {
	itemIDs, libraryIDs, seriesPaths, completed, err := st.ListUnappliedWatched(ctx)
	if err != nil {
		return
	}
	var tags []string
	applied := 0
	for i := range itemIDs {
		rowTags, err := qaRecsResolveWatchTags(ctx, st, reg, itemIDs[i], libraryIDs[i], seriesPaths[i])
		if err != nil {
			break
		}
		for _, tg := range rowTags {
			tags = append(tags, recs.NormalizeTag(tg))
		}
		applied = i + 1
	}
	if applied == 0 {
		return
	}
	_ = st.ApplyTagWeights(ctx, tags, completed[applied-1])
}

// qaRecsResolveWatchTags mirrors resolveWatchTags: an episode's tags live on
// its SERIES document (the watched row's library/path is the join), a
// film/tv item's on its own document; the chain resolves through
// ResolveGates over ONE batched prefs read; a vanished entity or unknown
// module is honest absence, not a failure.
func qaRecsResolveWatchTags(ctx context.Context, st *store.Store, reg *module.Registry, itemID string, libraryID int64, seriesPath string) ([]string, error) {
	var modID string
	var doc json.RawMessage
	if seriesPath == "" {
		it, err := st.GetItem(ctx, itemID, access.System())
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return nil, nil // vanished entity — honest absence
			}
			return nil, err
		}
		modID, doc = it.ModuleID, it.Document
	} else {
		sr, err := st.GetSeriesByPath(ctx, libraryID, seriesPath, access.System())
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return nil, nil // vanished entity — honest absence
			}
			return nil, err
		}
		modID, doc = sr.ModuleID, sr.Document
	}
	mod, err := reg.Get(modID)
	if err != nil {
		return nil, nil // unknown module — no chain, no carrier
	}
	prefs, err := st.ListMetadataSourcePrefs(ctx, modID, []int64{libraryID})
	if err != nil {
		return nil, err
	}
	return enrich.ResolveGenres(doc, enrich.ResolveGates(mod, prefs, libraryID)), nil
}

// qaRecsSeriesRow is the QA-local decode of the series wire shape plus the
// scored surface's fields (display_name, rec_score) and the watched stamp
// (watched-states D1) this joint asserts over.
type qaRecsSeriesRow struct {
	ID           string          `json:"id"`
	RelativePath string          `json:"relative_path"`
	Status       string          `json:"status"`
	Display      string          `json:"display_name"`
	RecScore     float64         `json:"rec_score"`
	Watched      bool            `json:"watched,omitempty"`
	Document     json.RawMessage `json:"document"`
}

type qaRecsSeriesList struct {
	Items []qaRecsSeriesRow `json:"items"`
}

// qaRecsListSeries lists a library's series through the joint's own api,
// carrying the optional sort opt-out ("" = the scored default).
func qaRecsListSeries(t *testing.T, j *qaRecsJoint, sort string) []qaRecsSeriesRow {
	t.Helper()
	u := j.baseURL + "/api/v1/series?library=" + strconv.FormatInt(j.lib, 10)
	if sort != "" {
		u += "&sort=" + sort
	}
	var resp qaRecsSeriesList
	if status := doRequest(t, j.w.client, http.MethodGet, u, j.w.token, nil, &resp); status != http.StatusOK {
		t.Fatalf("list series (sort=%q): HTTP %d, want 200", sort, status)
	}
	return resp.Items
}

// qaRecsOrder extracts the served order as relative paths.
func qaRecsOrder(rows []qaRecsSeriesRow) []string {
	out := make([]string, 0, len(rows))
	for _, r := range rows {
		out = append(out, r.RelativePath)
	}
	return out
}

// qaRecsScoreOf maps relative path → rec_score for the assertion reads.
func qaRecsScoreOf(rows []qaRecsSeriesRow) map[string]float64 {
	out := make(map[string]float64, len(rows))
	for _, r := range rows {
		out[r.RelativePath] = r.RecScore
	}
	return out
}

// qaRecsWantWeights builds the exact expected weight map: the learned pass
// must raise EXACTLY the watched series' genres (Alpha's genres stay absent —
// exact-map equality catches an extra key).
func qaRecsWantWeights() map[string]float64 {
	out := make(map[string]float64, len(qaRecsGenresZulu))
	for _, g := range qaRecsGenresZulu {
		out[recs.NormalizeTag(g)] = 1
	}
	return out
}

// qaRecsAwaitWeights polls the REAL store until the tag_weights table equals
// want exactly — the deterministic observable of the applied pass (the apply
// tx commits weights and the applied_at stamp together, so equality here
// implies the ledger row is stamped). Bounded; the failure dump carries both
// maps.
func qaRecsAwaitWeights(t *testing.T, st *store.Store, want map[string]float64) {
	t.Helper()
	deadline := time.Now().Add(qaRecsApplyTimeout)
	for time.Now().Before(deadline) {
		if got := qaRecsReadWeights(t, st); reflect.DeepEqual(got, want) {
			return
		}
		time.Sleep(probeInterval)
	}
	t.Fatalf("tag weights never reached %v; have %v", want, qaRecsReadWeights(t, st))
}

// qaRecsReadWeights reads the weight table as a normalized-key → weight map.
func qaRecsReadWeights(t *testing.T, st *store.Store) map[string]float64 {
	t.Helper()
	tags, weights, err := st.ListTagWeights(context.Background())
	if err != nil {
		t.Fatalf("ListTagWeights: %v", err)
	}
	out := make(map[string]float64, len(tags))
	for i, tg := range tags {
		out[tg] = float64(weights[i])
	}
	return out
}

// qaRecsAwaitGenres polls the series listing until BOTH fixture rows settle
// ready with their shikimori namespace landed carrying exactly the fixture's
// genre pair — the enrichment leg's deterministic observable. The failure
// dump carries both documents (the _stages carry a skipped stage's reason,
// the diagnosis surface).
func qaRecsAwaitGenres(t *testing.T, j *qaRecsJoint) {
	t.Helper()
	want := map[string][]string{
		qaRecsDirAlpha: qaRecsGenresAlpha,
		qaRecsDirZulu:  qaRecsGenresZulu,
	}
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for time.Now().Before(deadline) {
		if qaRecsGenresLanded(t, j, want) {
			return
		}
		time.Sleep(probeInterval)
	}
	docs := map[string]string{}
	for _, sr := range qaSerialListSeries(t, j.w.client, j.baseURL, j.w.token, j.lib) {
		docs[sr.RelativePath] = string(sr.Document)
	}
	t.Fatalf("genres never landed on both series documents (want %v); queue stats %+v; docs: %v",
		want, j.q.Stats(), docs)
}

// qaRecsGenresLanded reports whether every fixture row is ready with its
// expected genre pair (all-or-nothing: the await completes only on the full
// enrichment state).
func qaRecsGenresLanded(t *testing.T, j *qaRecsJoint, want map[string][]string) bool {
	t.Helper()
	byDir := map[string]qaSerialSeriesDTO{}
	for _, sr := range qaSerialListSeries(t, j.w.client, j.baseURL, j.w.token, j.lib) {
		byDir[sr.RelativePath] = sr
	}
	for dir, genres := range want {
		sr, ok := byDir[dir]
		if !ok || sr.Status != "ready" {
			return false
		}
		doc := parseAsyncDoc(t, sr.Document)
		ns, ok := doc.Sources["shikimori"]
		if !ok {
			return false
		}
		arr, _ := ns["genres"].([]any)
		if len(arr) != len(genres) {
			return false
		}
		for i, g := range arr {
			if s, _ := g.(string); s != genres[i] {
				return false
			}
		}
	}
	return true
}

// qaRecsProgressRow is the QA-local decode of the continue surface's scored
// wire shape plus the watched stamp (watched-states D1).
type qaRecsProgressRow struct {
	ItemID          string  `json:"item_id"`
	PositionSeconds int64   `json:"position_seconds"`
	RecScore        float64 `json:"rec_score"`
	Watched         bool    `json:"watched,omitempty"`
}

type qaRecsProgressList struct {
	Items []qaRecsProgressRow `json:"items"`
}

// qaRecsListProgress lists the continue surface through the joint's own api —
// the withdrawal default (no sort, no include).
func qaRecsListProgress(t *testing.T, j *qaRecsJoint) []qaRecsProgressRow {
	return qaRecsListProgressInclude(t, j, "", "")
}

// qaRecsListProgressInclude lists the continue surface with the sort and
// include opts ("" = query param omitted — the scored withdrawal default).
// The unknown-include 400 is asserted directly in the withdrawal subtest via
// doRequest: this helper fatals on any non-200 by construction.
func qaRecsListProgressInclude(t *testing.T, j *qaRecsJoint, sort, include string) []qaRecsProgressRow {
	t.Helper()
	q := url.Values{}
	if sort != "" {
		q.Set("sort", sort)
	}
	if include != "" {
		q.Set("include", include)
	}
	u := j.baseURL + "/api/v1/progress"
	if len(q) > 0 {
		u += "?" + q.Encode()
	}
	var resp qaRecsProgressList
	if status := doRequest(t, j.w.client, http.MethodGet, u, j.w.token, nil, &resp); status != http.StatusOK {
		t.Fatalf("list progress (sort=%q include=%q): HTTP %d, want 200", sort, include, status)
	}
	return resp.Items
}

// qaRecsPutProgress writes one playback position through the real route (the
// seam whose OnProgress fan-out fires the detector after the stored upsert).
// completed is the explicit completion intent (watched-states D3): true
// ledgers regardless of the 0.9 floor; false is the plain floor-only write.
func qaRecsPutProgress(t *testing.T, j *qaRecsJoint, itemID string, position int64, completed bool) {
	t.Helper()
	status := doRequest(t, j.w.client, http.MethodPut,
		j.baseURL+"/api/v1/progress/"+itemID, j.w.token,
		map[string]any{"position_seconds": position, "completed": completed}, nil)
	if status != http.StatusOK {
		t.Fatalf("PUT progress %s: HTTP %d, want 200", itemID, status)
	}
}

// TestRecsRoundtrip is the recommendation-sorting 5.1 joint.
func TestRecsRoundtrip(t *testing.T) {
	j := qaRecsStartJoint(t)
	ctx := context.Background()

	// --- scan: two one-episode serials, discovered/persisted 2+2 ---
	res := pbScanLibrary(t, j.w, j.lib)
	if res.Discovered != 4 || res.Persisted != 4 {
		t.Fatalf("scan discovered=%d persisted=%d, want 4/4 (2 series records + 2 episodes); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}

	byRel := indexByPath(t, listItems(t, j.w.client, j.baseURL, j.w.token, j.lib))
	zuluE01, ok := byRel[qaRecsDirZulu+"/"+qaRecsEpZulu]
	if !ok || zuluE01.ID == "" {
		t.Fatalf("Zulu E01 item missing; have %v", relKeys(byRel))
	}
	alphaE01, ok := byRel[qaRecsDirAlpha+"/"+qaRecsEpAlpha]
	if !ok || alphaE01.ID == "" {
		t.Fatalf("Alpha E01 item missing; have %v", relKeys(byRel))
	}

	t.Run("enrich lands genres on both series documents", func(t *testing.T) {
		qaRecsAwaitGenres(t, j)
		pbAwaitIdle(t, j.q, 30*time.Second) // drain the episode rows' chain too
	})

	t.Run("zero interest: equal tag counts tie into the alphabetical floor", func(t *testing.T) {
		if watched, err := j.w.st.ListWatched(ctx, access.System()); err != nil || len(watched) != 0 {
			t.Fatalf("pre-watch ledger = %v (err %v), want empty", watched, err)
		}
		rows := qaRecsListSeries(t, j, "")
		if got := qaRecsOrder(rows); !reflect.DeepEqual(got, []string{qaRecsDirAlpha, qaRecsDirZulu}) {
			t.Fatalf("scored default order = %v, want alphabetical [%s, %s] (the tie floor)",
				got, qaRecsDirAlpha, qaRecsDirZulu)
		}
		scores := qaRecsScoreOf(rows)
		for _, dir := range []string{qaRecsDirAlpha, qaRecsDirZulu} {
			if scores[dir] != qaRecsScoreBase {
				t.Fatalf("%s rec_score = %v, want %v (two tags, zero interest)", dir, scores[dir], qaRecsScoreBase)
			}
		}
	})

	t.Run("completion applies weights; the completed watch sinks below the unweighted grid", func(t *testing.T) {
		qaRecsPutProgress(t, j, zuluE01.ID, qaRecsWatchPos, false)

		// The detector leg ran synchronously inside the PUT (after the stored
		// upsert, before the response write): the ledger row is observable
		// the moment the PUT returns.
		watched, err := j.w.st.ListWatched(ctx, access.System())
		if err != nil {
			t.Fatalf("ListWatched: %v", err)
		}
		if len(watched) != 1 || watched[0] != zuluE01.ID {
			t.Fatalf("watched ledger = %v, want exactly [%s]", watched, zuluE01.ID)
		}

		// The wake-poked learning pass: exactly Zulu's genre pair gains one
		// point each; Alpha's genres stay absent (exact-map equality).
		qaRecsAwaitWeights(t, j.w.st, qaRecsWantWeights())
		if _, libIDs, paths, _, err := j.w.st.ListUnappliedWatched(ctx); err != nil || len(libIDs) != 0 {
			t.Fatalf("unapplied watched after apply = (%v rows, %v, err %v), want all stamped",
				len(libIDs), paths, err)
		}

		// The scored serve, under the watched partition (watched-states D4):
		// the completed series sinks below the unwatched one WHATEVER the tag
		// scores say — Zulu's learned score towers over Alpha's base and
		// still lands second, so the alphabetical-floor order no longer
		// flips.
		rows := qaRecsListSeries(t, j, "")
		if got := qaRecsOrder(rows); !reflect.DeepEqual(got, []string{qaRecsDirAlpha, qaRecsDirZulu}) {
			t.Fatalf("scored order = %v, want [%s, %s] (the watched partition sinks Zulu despite rec_score %v > %v)",
				got, qaRecsDirAlpha, qaRecsDirZulu, qaRecsScoreLearned, qaRecsScoreBase)
		}

		// The partition reorders, never rescores: Zulu still carries its
		// learned score, Alpha its base — the ordering is observable without
		// the score lying about it.
		scores := qaRecsScoreOf(rows)
		if scores[qaRecsDirZulu] != qaRecsScoreLearned {
			t.Fatalf("Zulu rec_score = %v, want %v (2 tags x (1 base + 1 learned))", scores[qaRecsDirZulu], qaRecsScoreLearned)
		}
		if scores[qaRecsDirAlpha] != qaRecsScoreBase {
			t.Fatalf("Alpha rec_score = %v, want %v (unwatched: base weights untouched)", scores[qaRecsDirAlpha], qaRecsScoreBase)
		}

		// The series watched flags (watched-states D1): the single-episode
		// series whose one episode completed is all-episodes watched — true
		// on the wire; Alpha carries no ledger row, and omitempty keeps the
		// flag absent (decoded false — true-only on the wire).
		watchedByDir := map[string]bool{}
		for _, r := range rows {
			watchedByDir[r.RelativePath] = r.Watched
		}
		if !watchedByDir[qaRecsDirZulu] || watchedByDir[qaRecsDirAlpha] {
			t.Fatalf("series watched flags = %v, want %s watched, %s absent", watchedByDir, qaRecsDirZulu, qaRecsDirAlpha)
		}

		// The opt-out: sort=path restores the path order unscored (the
		// omitempty rec_score decodes as 0).
		pathRows := qaRecsListSeries(t, j, "path")
		if got := qaRecsOrder(pathRows); !reflect.DeepEqual(got, []string{qaRecsDirAlpha, qaRecsDirZulu}) {
			t.Fatalf("sort=path order = %v, want path order [%s, %s]", got, qaRecsDirAlpha, qaRecsDirZulu)
		}
		for _, r := range pathRows {
			if r.RecScore != 0 {
				t.Fatalf("sort=path row %s carries rec_score %v, want unscored (field omitted)", r.RelativePath, r.RecScore)
			}
		}
	})

	t.Run("rewatch is a ledger no-op: weights unchanged", func(t *testing.T) {
		qaRecsPutProgress(t, j, zuluE01.ID, qaRecsWatchPos, false) // crosses 90% again

		watched, err := j.w.st.ListWatched(ctx, access.System())
		if err != nil {
			t.Fatalf("ListWatched: %v", err)
		}
		if len(watched) != 1 || watched[0] != zuluE01.ID {
			t.Fatalf("watched ledger after rewatch = %v, want exactly [%s] (the PK no-op)", watched, zuluE01.ID)
		}
		if _, libIDs, _, _, err := j.w.st.ListUnappliedWatched(ctx); err != nil || len(libIDs) != 0 {
			t.Fatalf("unapplied watched after rewatch = %d rows (err %v), want 0 (nothing re-queued)", len(libIDs), err)
		}
		// Deterministic without a wait: any wake-poked pass finds an empty
		// derived queue and writes nothing, whenever it runs.
		if got := qaRecsReadWeights(t, j.w.st); !reflect.DeepEqual(got, qaRecsWantWeights()) {
			t.Fatalf("weights after rewatch = %v, want unchanged %v", got, qaRecsWantWeights())
		}
		// The partition order is stable across the rewatch: the completed
		// series stays sunk, its score unstamped-double.
		rows := qaRecsListSeries(t, j, "")
		if got := qaRecsOrder(rows); !reflect.DeepEqual(got, []string{qaRecsDirAlpha, qaRecsDirZulu}) {
			t.Fatalf("scored order after rewatch = %v, want unchanged [%s, %s] (the watched partition)",
				got, qaRecsDirAlpha, qaRecsDirZulu)
		}
		if scores := qaRecsScoreOf(rows); scores[qaRecsDirZulu] != qaRecsScoreLearned || scores[qaRecsDirAlpha] != qaRecsScoreBase {
			t.Fatalf("scores after rewatch = %v, want unchanged (no double-count)", scores)
		}
	})

	t.Run("rail withdrawal: the completed watch leaves the default rail; include=watched restores it", func(t *testing.T) {
		// The withdrawal default (watched-states D2), BOTH branches: the
		// ledgered row is gone from the scored default AND from the
		// sort=recent opt-out — a completed watch has no resume point.
		if got := qaRecsListProgress(t, j); len(got) != 0 {
			t.Fatalf("default rail rows = %+v, want none (the completed watch's position is spent)", got)
		}
		if got := qaRecsListProgressInclude(t, j, "recent", ""); len(got) != 0 {
			t.Fatalf("sort=recent rows = %+v, want none (the withdrawal holds in the opt-out branch)", got)
		}

		// ?include=watched restores the row in both branches, stamped
		// watched. The scored default scores the completed entity tags-only
		// (the series-weighted learned score, no resume bonus); the recent
		// opt-out serves unscored exactly as before.
		restored := qaRecsListProgressInclude(t, j, "", "watched")
		if len(restored) != 1 || restored[0].ItemID != zuluE01.ID {
			t.Fatalf("include=watched rows = %+v, want exactly [%s]", restored, zuluE01.ID)
		}
		if !restored[0].Watched {
			t.Fatalf("restored row %+v carries no watched stamp", restored[0])
		}
		if restored[0].RecScore != qaRecsScoreLearned {
			t.Fatalf("restored row rec_score = %v, want %v (completed: tags only, no inProgress bonus)",
				restored[0].RecScore, qaRecsScoreLearned)
		}
		recent := qaRecsListProgressInclude(t, j, "recent", "watched")
		if len(recent) != 1 || recent[0].ItemID != zuluE01.ID || !recent[0].Watched {
			t.Fatalf("sort=recent&include=watched rows = %+v, want exactly [%s] watched", recent, zuluE01.ID)
		}
		if recent[0].RecScore != 0 {
			t.Fatalf("sort=recent restored row carries rec_score %v, want unscored (field omitted)", recent[0].RecScore)
		}

		// The strict parse: an unknown include value is a 400, never a
		// silently served row set (the same posture as the sort grammar).
		status := doRequest(t, j.w.client, http.MethodGet,
			j.baseURL+"/api/v1/progress?include=all", j.w.token, nil, &qaRecsProgressList{})
		if status != http.StatusBadRequest {
			t.Fatalf("include=all: HTTP %d, want 400 (the strict include parse)", status)
		}
	})

	t.Run("completed intent ledgers below the floor", func(t *testing.T) {
		// The 0.3 s fixture has no integer-second mid position, so 0 s — 0 %,
		// strictly below the 0.9 floor — carries the below-floor side; the
		// floor's satisfied side is the completion subtest's 2 s write.
		qaRecsPutProgress(t, j, alphaE01.ID, 0, false)
		if watched, err := j.w.st.ListWatched(ctx, access.System()); err != nil || len(watched) != 1 || watched[0] != zuluE01.ID {
			t.Fatalf("ledger after the plain below-floor write = %v (err %v), want still exactly [%s] (the floor held)",
				watched, err, zuluE01.ID)
		}

		// The explicit completion intent (watched-states D3): the SAME
		// below-floor position with completed:true ledgers — intent needs no
		// duration, no floor crossing.
		qaRecsPutProgress(t, j, alphaE01.ID, 0, true)
		watched, err := j.w.st.ListWatched(ctx, access.System())
		if err != nil {
			t.Fatalf("ListWatched: %v", err)
		}
		got := append([]string(nil), watched...)
		sort.Strings(got)
		if want := []string{alphaE01.ID, zuluE01.ID}; !reflect.DeepEqual(got, want) {
			t.Fatalf("ledger after the intent write = %v, want exactly %v", watched, want)
		}

		// The series flag follows the all-episodes law the same walk derives:
		// Alpha's last episode completed, so BOTH series now stamp watched —
		// the grid's partition sinks both, and within the watched leaf the
		// intent write's wake has applied Alpha's genre weights too (both
		// series score the learned 4), so the name floor orders them.
		rows := qaRecsListSeries(t, j, "")
		scores := qaRecsScoreOf(rows)
		if scores[qaRecsDirZulu] != qaRecsScoreLearned || scores[qaRecsDirAlpha] != qaRecsScoreLearned {
			t.Fatalf("all-watched scores = %v, want both %v (the intent write learned Alpha's genres too)", scores, qaRecsScoreLearned)
		}
		if got := qaRecsOrder(rows); !reflect.DeepEqual(got, []string{qaRecsDirAlpha, qaRecsDirZulu}) {
			t.Fatalf("all-watched grid order = %v, want [%s, %s] (within-leaf score tie, name floor)",
				got, qaRecsDirAlpha, qaRecsDirZulu)
		}
		for _, r := range rows {
			if !r.Watched {
				t.Fatalf("series %s carries no watched flag after its last episode completed", r.RelativePath)
			}
		}
	})
}
